<script setup lang="ts">import {onMounted,ref} from 'vue';import ManagementLayout from '@/components/ManagementLayout.vue';import {platformApi,type SchoolClass,type Classroom,type Device} from '@/api/platform';const classes=ref<SchoolClass[]>([]);const classrooms=ref<Classroom[]>([]);const devices=ref<Device[]>([]);const classId=ref(0);const classroomId=ref(0);const deviceId=ref(0);const ticket=ref('');const expiresAt=ref('');const error=ref('');async function load(){try{const [c,r,d]=await Promise.all([platformApi.classes(),platformApi.classrooms(),platformApi.devices()]);classes.value=c.data.items;classrooms.value=r.data;devices.value=d.data}catch{error.value='无法加载课堂设备信息。'}}async function create(){error.value='';try{const result=await platformApi.createTicket({classId:classId.value,classroomId:classroomId.value,deviceId:deviceId.value});ticket.value=result.data.ticket;expiresAt.value=result.data.expiresAt}catch{error.value='设备、教室与班级必须存在有效绑定。'}}onMounted(load)</script>
<template><ManagementLayout><h1>课堂设备准备</h1><p class="muted">选择班级、教室和大屏设备，生成本次课堂进入凭证。</p><div class="panel scan-form"><label>班级<select v-model.number="classId"><option :value="0">请选择班级</option><option v-for="item in classes" :key="item.id" :value="item.id">{{item.name}}</option></select></label><label>教室<select v-model.number="classroomId"><option :value="0">请选择教室</option><option v-for="item in classrooms" :key="item.id" :value="item.id">{{item.name}}</option></select></label><label>设备<select v-model.number="deviceId"><option :value="0">请选择设备</option><option v-for="item in devices" :key="item.id" :value="item.id">{{item.name}}（{{item.status}}）</option></select></label><button class="button" @click="create">生成课堂进入凭证</button><p v-if="error" class="bad">{{error}}</p><div v-if="ticket" class="ticket"><strong>课堂进入凭证</strong><code>{{ticket}}</code><small>有效期至：{{expiresAt}}</small></div></div></ManagementLayout></template><style scoped>.scan-form{display:grid;gap:15px;max-width:620px}.scan-form label{display:grid;gap:7px;font-weight:700}.scan-form select{height:40px;border:1px solid #efd9c8;background:#fffdf9;border-radius:10px;padding:0 10px}.ticket{display:grid;gap:10px;background:#edf9f4;border-radius:10px;padding:18px;color:#347b69}.ticket code{word-break:break-all;background:#fff;padding:12px;border-radius:7px}
</style>
